//! D10 lexicon: the embedded word tables and the English-versus-Vietnamese score.
//!
//! Everything here is `static` data in the binary (`include_str!`/`include_bytes!`
//! of files generated by `scripts/gen_wordlists.py`); nothing is built at run
//! time, nothing allocates. Lookups are binary searches over sorted text and
//! only run at a word break (or, for [`rime_prefix_ok`], on a 112-entry sorted
//! array). Sources and licences: `crates/vkb-core/data/THIRD_PARTY.md`.
//!
//! **Syllable key.** A Vietnamese syllable is looked up by an ASCII key: each
//! letter lowercased, then its mark (`^` circumflex, `(` breve, `+` horn), `đ`
//! is `D`, and the tone digit (`1` sắc … `5` nặng, none = no digit) at the very
//! end. `tiếng` is `tie^ng1`. Tone placement (old or new style) never matters.

use crate::letters::{Letter, Mark, Tone};

mod consts {
    include!("../data/consts.rs");
}
use consts::RIME_PREFIXES;

mod bigrams {
    include!("../data/bigrams.rs");
}
use bigrams::{ENGLISH_PAIRS, VIETNAMESE_PAIRS};

static ENGLISH: &str = include_str!("../data/english.txt");
static VI: &str = include_str!("../data/vi.txt");

/// FNV-1a 32-bit, the hash `pairs.bin` is keyed by.
pub const FNV_BASIS: u32 = 0x811C_9DC5;

pub fn fnv_extend(mut hash: u32, bytes: &[u8]) -> u32 {
    for &byte in bytes {
        hash = (hash ^ u32::from(byte)).wrapping_mul(0x0100_0193);
    }
    hash
}

/// An English word that Telex would compose into something else.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EnglishWord {
    /// 1..=7: SCOWL size 10, 20, 35, 40, 50, 55, 60 (tech words count as 2).
    pub level: u8,
    /// Vietnamese text borrows it as-is (`teen`, `mix`).
    pub loan: bool,
    /// A programming word (`cos`, `max`, `return`).
    pub tech: bool,
    /// A short code identifier (`res`, `os`, `buf`).
    pub ident: bool,
    /// A name or brand (`Mary`, `Asus`).
    pub name: bool,
}

/// Binary search over sorted lines. `key_len(line)` is the length of the part
/// of the line that is the sort key.
fn find_line<'a>(blob: &'a str, probe: &[u8], key_len: fn(&[u8]) -> usize) -> Option<&'a [u8]> {
    let bytes = blob.as_bytes();
    let (mut lo, mut hi) = (0usize, bytes.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let start = bytes[..mid].iter().rposition(|&b| b == b'\n').map_or(0, |p| p + 1);
        let end = bytes[start..].iter().position(|&b| b == b'\n').map_or(bytes.len(), |p| start + p);
        // Tolerate CRLF: a checkout with autocrlf must not leave a `\r` in the key or the value.
        let line = &bytes[start..end];
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        match line[..key_len(line)].cmp(probe) {
            std::cmp::Ordering::Equal => return Some(line),
            std::cmp::Ordering::Less => lo = end + 1,
            std::cmp::Ordering::Greater => hi = start,
        }
    }
    None
}

fn english_key_len(line: &[u8]) -> usize {
    line.len() - 1
}

fn vi_key_len(line: &[u8]) -> usize {
    line.iter().position(|&b| b == b' ').unwrap_or(line.len())
}

/// `word` is lowercase ASCII.
pub fn english_word(word: &[u8]) -> Option<EnglishWord> {
    english_in(ENGLISH, word)
}

fn english_in(blob: &str, word: &[u8]) -> Option<EnglishWord> {
    let line = find_line(blob, word, english_key_len)?;
    let tag = *line.last()?;
    let plain = EnglishWord { level: 1, loan: false, tech: false, ident: false, name: false };
    Some(match tag {
        b'1'..=b'7' => EnglishWord { level: tag - b'0', ..plain },
        b'a'..=b'g' => EnglishWord { level: tag - b'a' + 1, loan: true, ..plain },
        b'h'..=b'n' => EnglishWord { level: tag - b'h' + 1, ident: true, tech: true, ..plain },
        b'o'..=b'u' => EnglishWord { level: tag - b'o' + 1, name: true, ..plain },
        _ => EnglishWord { level: tag.wrapping_sub(b'A') + 1, tech: true, ..plain },
    })
}

/// How often the corpora saw the syllable (0 = not a common Vietnamese word).
pub fn vi_count(key: &[u8]) -> u32 {
    vi_count_in(VI, key)
}

fn vi_count_in(blob: &str, key: &[u8]) -> u32 {
    let Some(line) = find_line(blob, key, vi_key_len) else {
        return 0;
    };
    line[vi_key_len(line) + 1..]
        .iter()
        .fold(0u32, |acc, &d| acc * 10 + u32::from(d.wrapping_sub(b'0')))
}

/// English words that mark the previous word as English even when they are also
/// plausible Vietnamese toneless syllables. Sorted.
static FUNCTION_WORDS: &[&str] = &[
    "and", "any", "are", "at", "be", "but", "by", "each", "for", "from", "have", "her", "his", "how", "in", "is", "it", "its", "many", "my", "not", "now", "of", "on", "or", "our", "she", "some", "such", "that", "the", "their", "them", "then", "there", "these", "they", "this", "those", "up", "was", "were", "what", "when", "where", "which", "who", "will", "with", "would", "you", "your",
];

/// Determiners and possessives. Only counted when the word stayed raw or was
/// restored (`this` composes to `thí` and is then Vietnamese).
static DETERMINERS: &[&str] = &[
    "any", "each", "every", "her", "his", "its", "my", "our", "some", "the", "their", "these", "this", "those",
    "your",
];

pub fn is_determiner(word: &[u8]) -> bool {
    DETERMINERS.iter().any(|w| w.as_bytes() == word)
}

/// More closed-class words that a Vietnamese reading shares (`as`/á, `if`/ì, `us`/ú, `too`/tô,
/// `has`/há, `also`, `own`, `does`). Owner (2026-11-02): like the function words they keep the
/// 0.2.8 behaviour (Vietnamese unless English context stands to their left); the pair tables and
/// the one-word-back rule never apply to them.
static CLOSED_EXTRA: &[&str] = &["also", "as", "does", "has", "if", "us", "own", "too"];

/// A function word, determiner or other closed-class word.
pub fn is_closed_word(word: &[u8]) -> bool {
    is_function_word(word) || is_determiner(word) || CLOSED_EXTRA.iter().any(|w| w.as_bytes() == word)
}

/// English words the engine keeps Vietnamese although the syllable corpus lacks the reading.
pub fn real_but_uncounted(word: &[u8]) -> bool {
    REAL_BUT_UNCOUNTED.contains(&word)
}

pub fn is_function_word(word: &[u8]) -> bool {
    FUNCTION_WORDS.binary_search_by(|w| w.as_bytes().cmp(word)).is_ok()
}

/// Write the syllable key of `letters` (+ `tone`) into `out`; returns its length.
/// `None` when a letter has no ASCII form or the word is longer than `out`.
pub fn syllable_key(letters: &[Letter], tone: Tone, out: &mut [u8; 48]) -> Option<usize> {
    let mut len = 0usize;
    for letter in letters {
        let base = letter.base();
        if !base.is_ascii_alphabetic() {
            return None;
        }
        let need = 2;
        if len + need + 1 > out.len() {
            return None;
        }
        if base == 'd' && letter.mark == Mark::Bar {
            out[len] = b'D';
            len += 1;
            continue;
        }
        out[len] = base as u8;
        len += 1;
        match letter.mark {
            Mark::Circumflex => {
                out[len] = b'^';
                len += 1;
            }
            Mark::Breve => {
                out[len] = b'(';
                len += 1;
            }
            Mark::Horn => {
                out[len] = b'+';
                len += 1;
            }
            Mark::Bar | Mark::None => {}
        }
    }
    if tone != Tone::None {
        out[len] = b'0' + tone.index() as u8;
        len += 1;
    }
    Some(len)
}

/// `true` when the mark-free, tone-free rime `plain` (the letters after the
/// onset) is a prefix of some Vietnamese rime.
pub fn rime_prefix_ok(plain: &[u8]) -> bool {
    if plain.len() > 5 {
        return false;
    }
    let mut code = 0u32;
    for &byte in plain {
        let symbol = match byte {
            b'a' => 1,
            b'e' => 2,
            b'i' => 3,
            b'o' => 4,
            b'u' => 5,
            b'y' => 6,
            b'c' => 7,
            b'h' => 8,
            b'm' => 9,
            b'n' => 10,
            b'p' => 11,
            b't' => 12,
            b'g' => 13,
            _ => return false,
        };
        code = code * 14 + symbol;
    }
    RIME_PREFIXES.binary_search(&code).is_ok()
}

// ---------------------------------------------------------------------------
// The score
// ---------------------------------------------------------------------------

/// What stands left of the word being decided.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Left {
    /// Start of a line or sentence (after `. ! ?`, Enter, a caret move or a focus change).
    Start,
    /// After a comma, semicolon or colon: no left word to use, but not a sentence start.
    Clause,
    /// Right after a code operator or bracket (`x = `, `foo(`, `a + `).
    Code,
    /// The previous word was an English function word (`you`, `in`, `with`).
    Function,
    /// The previous word was a determiner or possessive that is no Vietnamese text
    /// (`the`, `my`, `your`): the next word is English if its keys are a listed word.
    Determiner,
    /// The previous word was English or code; `hash` is the FNV state after `word + " "`,
    /// `run` how many English words in a row end here (`ok` is one, `the new dashboard` three).
    English { hash: u32, run: u32, listed: bool },
    /// The previous word was this Vietnamese syllable: its corpus count and the
    /// FNV state after `key + " "`.
    Vietnamese { count: u32, hash: u32 },
}

/// A Vietnamese syllable at least this common is "protected": it flips to
/// English only on positive English evidence (English or code on the left, a
/// code app at the start of a line, a known English collocation), never because
/// a word pair is missing from the table.
pub const PROTECTED_COUNT: u32 = 100;
/// A Vietnamese syllable seen this often has a common reading: an English function
/// word on the left does not take it away.
const KNOWN_COUNT: u32 = 4;
const fn colloc(previous: &str, english: &str) -> u32 {
    let mut hash = fnv_const(FNV_BASIS, previous.as_bytes());
    hash = fnv_const(hash, b" ");
    fnv_const(hash, english.as_bytes())
}

const fn fnv_const(mut hash: u32, bytes: &[u8]) -> u32 {
    let mut i = 0;
    while i < bytes.len() {
        hash = (hash ^ bytes[i] as u32).wrapping_mul(0x0100_0193);
        i += 1;
    }
    hash
}

/// Vietnamese word + English word pairs that are real Vietnamese usage of an
/// English word: `previous syllable key + " " + english word`. Small on purpose;
/// these beat the protection of a common Vietnamese reading (`tên`).
static COLLOCATIONS: [u32; 6] = [
    colloc("hay", "mix"),
    colloc("tuo^i3", "teen"),
    colloc("nhom1", "teen"),
    colloc("kie^u3", "teen"),
    colloc("cach1", "teen"),
    colloc("thich1", "mix"),
];

/// English word + word pairs that are English: `I like mix`.
static EN_COLLOCATIONS: &[u32] = &[colloc("like", "mix"), colloc("love", "mix")];

/// Vietnamese word + English-looking word pairs that are really Vietnamese
/// (`nước mix` is `nước mĩ`): they force the Vietnamese reading.
static VI_COLLOCATIONS: &[u32] = &[
    colloc("nu+o+c1", "mix"),
    colloc("nguo+i2", "mix"),
    colloc("quo^c1", "mix"),
    colloc("ca1", "tree"),
];

/// The only phrases the one-word-back correction may turn into English: an
/// explicit, small list (owner: when in doubt, Vietnamese). The first word is
/// what a line start keeps as Vietnamese (`Mã`, `Sĩ`), the second certainly
/// English.
static BACK_PAIRS: &[u32] = &[
    colloc("max", "speed"),
    colloc("max", "pro"),
    colloc("max", "plus"),
    colloc("six", "pack"),
];
static BACK_FIRST: &[&str] = &["max", "six"];

/// English words whose Vietnamese reading is a real word that the syllable corpus lacks.
static REAL_BUT_UNCOUNTED: &[&[u8]] = &[b"gas", b"nor", b"here"];

/// Compounds the corpus cannot attest but the owner needs (`rôm rả`, `rôm sảy`): English
/// `room` followed by these typed keys is rewritten to `rôm` (one word back).
static BACK_VI_PAIRS: &[u32] = &[
    colloc("room", "rar"),
    colloc("room", "sayr"),
    colloc("turn", "murn"),
    colloc("keen", "keen"),
    colloc("vary", "cas"),
    colloc("vary", "neens"),
];

/// Hand-written, short on purpose: compounds that 0.2.8 typed right and that the stand-alone
/// rule (`count == 0` -> English) would otherwise break, because the Vietnamese corpus does not
/// attest them (it has 33k sentences). `rôm rả`, `rôm sảy`, `tủn mủn`, `kên kên`, `vảy cá`,
/// `vảy nến` are rewritten one word back (`BACK_VI_PAIRS`); `cá trê` is a previous-word pair
/// (`VI_COLLOCATIONS`), and the second `keen` of `kên kên` is Vietnamese after English `keen`
/// (`VI_AFTER_ENGLISH`). Add an entry only for a real compound the owner confirms.
static VI_AFTER_ENGLISH: &[u32] = &[colloc("keen", "keen")];

pub fn back_vi_pair(first: &[u8], second: &[u8]) -> bool {
    let hash = fnv_extend(fnv_extend(fnv_extend(FNV_BASIS, first), b" "), second);
    BACK_VI_PAIRS.contains(&hash)
}

/// English pair `first second` (lowercase words) attested in the English corpus table.
pub fn en_pair_of(first: &[u8], second: &[u8]) -> bool {
    let hash = fnv_extend(fnv_extend(fnv_extend(FNV_BASIS, first), b" "), second);
    ENGLISH_PAIRS.binary_search(&hash).is_ok()
}

/// Vietnamese pair attested in the Vietnamese corpus table; `hash` = FNV of `key1 key2`.
pub fn vi_pair(hash: u32) -> bool {
    VIETNAMESE_PAIRS.binary_search(&hash).is_ok()
}

pub fn back_first(typed: &[u8]) -> bool {
    BACK_FIRST.iter().any(|w| w.as_bytes() == typed)
}

pub fn back_pair(first: &[u8], second: &[u8]) -> bool {
    let hash = fnv_extend(fnv_extend(fnv_extend(FNV_BASIS, first), b" "), second);
    BACK_PAIRS.contains(&hash)
}

/// Known acronyms typed in capitals (`USA`, `UX`, `OS`): Telex would turn the
/// vowel and the S into `ÚA`, `Ũ`, `Ó`. Matched case-sensitively (letters and
/// digits, 2 to 5 characters).
static ACRONYMS: &[&str] = &[
    "AI", "API", "AR", "ASAP", "AWS", "B2B", "B2C", "CEO", "CFO", "CH4", "CMS", "CO2",     "CPU", "CRM", "CSS", "CTO", "DNS", "EU", "EXO", "FAQ", "FTP", "GCP", "GPS",
    "GPU", "H2O", "HDD", "HDMI", "HR", "HTML", "HTTP", "HTTPS", "IDE", "IMF", "IP", "IT", "JPG",
    "JPEG", "JSON", "KPI", "LAN", "LCD", "LED", "LLM", "MP3", "MP4", "NASA", "NFT", "NO2", "O2",
    "OCR", "OKR", "OS", "OTP", "PDF", "PM", "PNG", "PR", "QA", "QR", "RAM", "REST", "ROI", "ROM",
    "SAS", "SDK", "SEO", "SMS", "SO2", "SOS", "SQL", "SSD", "SSH", "SSL", "SVG", "TCP", "TLS",
    "TOS", "UDP", "UI", "UK", "UN", "URI", "URL", "US", "USA", "USB", "UX", "VPN", "VR", "WAN",
    "XML", "XR",
];

/// Lowercase tokens that are clearly not Vietnamese words.
static LOWER_ACRONYMS: &[&str] = &["asap", "sos", "usa"];

/// `token` is a known acronym typed the way acronyms are: capitals, or one of
/// the few lowercase ones that are unmistakable.
pub fn is_acronym(token: &[u8]) -> bool {
    if token.len() < 2 || token.len() > 5 {
        return false;
    }
    ACRONYMS.iter().any(|a| a.as_bytes() == token)
        || LOWER_ACRONYMS.iter().any(|a| a.as_bytes() == token)
}

/// Should the typed English word replace the composed text?
///
/// The rule is conservative. **A plausible Vietnamese syllable wins** (in the
/// corpus list or only well-formed), in every app. It flips only on positive
/// evidence: an English function word or English word on the left, a code
/// context, a known collocation, or the keyword `if` at a line start. When the
/// composed text cannot be Vietnamese (`ủe`, `wể`, `pas`) the list decides.
/// The app profile alone never flips anything; a code editor only lets a code
/// identifier (`res`, `os`) stand after a code word, bracket or operator.
///
/// `vi_key` is the composed Vietnamese syllable's key, `typed` the lowercase
/// typed keys, `plausible` whether the composed text could be Vietnamese.
pub fn english_wins(
    vi_key: &[u8],
    typed: &[u8],
    word: EnglishWord,
    left: Left,
    code_app: bool,
    plausible: bool,
    capital: bool,
) -> bool {
    let count = vi_count(vi_key);
    let protected = count >= PROTECTED_COUNT;
    // A rarer English form (plural, rare word) against a real Vietnamese word.
    let weak = word.level > 2 && !word.loan && !word.name && count > 0;
    // Short identifiers (`res`, `os`, `arr`) only in a code editor after code.
    if word.ident {
        return code_app && matches!(left, Left::English { .. } | Left::Code | Left::Function);
    }
    if let Left::Vietnamese { hash, .. } = left {
        let phrase = fnv_extend(hash, typed);
        if VI_COLLOCATIONS.contains(&phrase) {
            return false;
        }
        if COLLOCATIONS.contains(&phrase) {
            return true;
        }
        // An attested Vietnamese pair (`phòng rôm`, `mã nguồn`) is Vietnamese, whatever the
        // English reading would do; it also wins over an English pair for now.
        if VIETNAMESE_PAIRS.binary_search(&fnv_extend(hash, vi_key)).is_ok() {
            return false;
        }
    }
    // `the car`, `my phone`: after a determiner a listed English word is English, when
    // it is a real common word (not `sangs`, `seeps`, `thees`, `thee`).
    if matches!(left, Left::Determiner) {
        let common = word.level <= 3 || word.loan || word.tech || word.name;
        return common && typed != b"thee";
    }
    if !plausible {
        return true;
    }
    if let Left::English { hash, .. } = left {
        if VI_AFTER_ENGLISH.contains(&fnv_extend(hash, typed)) {
            return false;
        }
    }
    // Owner (2026-11-02): `room` is English, there is no Vietnamese `rôm` (`meeting room`,
    // `phòng room`, `room 5`). A common listed English word whose Vietnamese reading is
    // absent from the syllable corpus is not a stand-alone Vietnamese word, so the typed
    // keys win in every context. Threshold: count == 0, because the counts of the words
    // that must stay Vietnamese overlap those that must not (corpus counts):
    // room/rôm 0, soon/sôn 0, door/dổ 0, more/mỏe 0, tree/trê 0 flip to English;
    // see/sê 2, tax/tã 2, box/bõ 1, bus/bú 1, max/mã 31, mix/mĩ 21, moon/môn 60,
    // six/sĩ 173 stay Vietnamese (any count above 0 is "doubt -> Vietnamese").
    // `gas`/`gá` is absent from the corpus but is a real word (`gá chồng`), so it is
    // listed in `REAL_BUT_UNCOUNTED`. Only SCOWL level 1 (the commonest English words) qualifies: the level 3+ words (`sons`, `lair`, `chow`, `mar`) collide with real Vietnamese words the corpus also lacks (`són`, `lải`, `chơ`, `mả`).
    // `nor`/`nỏ` is such a word too.
    if count == 0 && !is_closed_word(typed) && word.level == 1 && !word.loan && !REAL_BUT_UNCOUNTED.contains(&typed)
    {
        return true;
    }
    match left {
        // `the car`, `my tips`, `with cups`: an English noun, even a plural or a
        // word that collides with a common Vietnamese one.
        // Not when the word has a common Vietnamese reading (`you má`, `check in có`).
        Left::Function => count < KNOWN_COUNT,
        // Owner (2026-11-02): after an English word a listed English word stays English
        // even when its keys compose a real Vietnamese word, but only when the two words
        // form a pair attested in English sentences (`meeting room`, `mail box`; not
        // `file max`). No bigram hit -> Vietnamese. `listed`: the left word is English
        // text, not a raw typo. The restore hotkey flips it back.
        Left::English { hash, run, listed } => {
            (listed && !is_closed_word(typed) && ENGLISH_PAIRS.binary_search(&fnv_extend(hash, typed)).is_ok())
                || (run >= 2 && is_function_word(typed) && !protected && !weak)
                || EN_COLLOCATIONS.contains(&fnv_extend(hash, typed))
        }
        // `x = max`, `foo(cos`: a code context.
        // After a code operator or bracket: evidence only in a code app, and only
        // for a lowercase programming word (`x = cos`, `f(max`). A capitalised
        // or plural-shaped Vietnamese syllable (`(Mas`, `**Cams`) is a sentence.
        Left::Code => code_app && word.tech && !capital,
        // A keyword whose Vietnamese twin is rare (`ì`).
        Left::Start => typed == b"if",
        Left::Determiner | Left::Clause | Left::Vietnamese { .. } => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_and_findable() {
        assert_eq!(english_word(b"user").map(|w| (w.level, w.loan)), Some((1, false)));
        assert_eq!(english_word(b"teen").map(|w| (w.level, w.loan)), Some((3, true)));
        assert!(english_word(b"res").unwrap().ident);
        assert!(english_word(b"harry").unwrap().name);
        assert!(english_word(b"cos").unwrap().tech);
        assert_eq!(english_word(b"zzzz"), None);
        assert!(vi_count(b"co1") > 1000);
        assert_eq!(vi_count(b"zzzz"), 0);
        for window in ENGLISH.lines().collect::<Vec<_>>().windows(2) {
            assert!(window[0][..window[0].len() - 1] < window[1][..window[1].len() - 1]);
        }
    }

    #[test]
    fn embedded_tables_have_no_carriage_return() {
        // A Windows checkout with core.autocrlf=true must still give LF (.gitattributes).
        assert!(!ENGLISH.contains('\r'), "english.txt has a CR");
        assert!(!VI.contains('\r'), "vi.txt has a CR");
    }

    #[test]
    fn crlf_copies_of_the_tables_give_the_same_lookups() {
        let english_crlf = ENGLISH.replace("\r\n", "\n").replace('\n', "\r\n");
        let vi_crlf = VI.replace("\r\n", "\n").replace('\n', "\r\n");
        for line in ENGLISH.lines() {
            let word = &line.as_bytes()[..line.len() - 1];
            assert!(english_in(&english_crlf, word).is_some(), "{line}");
            assert_eq!(english_in(&english_crlf, word), english_in(ENGLISH, word), "{line}");
        }
        for line in VI.lines() {
            let key = line.split(' ').next().unwrap().as_bytes();
            assert_eq!(vi_count_in(&vi_crlf, key), vi_count_in(VI, key), "{line}");
            assert!(vi_count_in(&vi_crlf, key) > 0, "{line}");
        }
        assert_eq!(english_in(&english_crlf, b"zzzz"), None);
        assert_eq!(vi_count_in(&vi_crlf, b"zzzz"), 0);
    }

    #[test]
    fn rime_prefixes() {
        for ok in ["u", "uo", "uon", "uong", "ie", "iec", "yeu", "oanh", "a"] {
            assert!(rime_prefix_ok(ok.as_bytes()), "{ok}");
        }
        for bad in ["uit", "oo", "ay" , "aa", "ib", "uoo", "ot", "eeee"] {
            // "ay" and "ot" are real rimes: only the genuinely impossible ones fail.
            let real = matches!(bad, "ay" | "ot");
            assert_eq!(rime_prefix_ok(bad.as_bytes()), real, "{bad}");
        }
    }

    #[test]
    fn pair_tables_are_sorted() {
        assert!(ENGLISH_PAIRS.windows(2).all(|w| w[0] < w[1]));
        assert!(VIETNAMESE_PAIRS.windows(2).all(|w| w[0] < w[1]));
        assert!(en_pair_of(b"mail", b"box") && !en_pair_of(b"file", b"max"));
    }

    #[test]
    fn function_words_are_sorted() {
        assert!(FUNCTION_WORDS.windows(2).all(|w| w[0] < w[1]));
    }
}
